@tailwind base;
@tailwind components;
@tailwind utilities;

/* --- CONFIGURACIÓN GLOBAL --- */
html, body, #root {
    cursor: auto !important;
    background-color: black;
}

/* --- INTERACTION SYSTEM --- */
.interaction-target {
    transition: filter 0.2s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    cursor: crosshair; /* Tactical feel */
    pointer-events: auto !important; /* CRITICAL: Ensures interaction works inside pointer-events-none containers */
}

/* White Outline Effect using multiple drop-shadows for a stroke-like appearance on PNGs */
.interaction-target:hover {
    filter: drop-shadow(1px 0 0 white) 
            drop-shadow(-1px 0 0 white) 
            drop-shadow(0 1px 0 white) 
            drop-shadow(0 -1px 0 white)
            brightness(1.1);
    z-index: 50;
}

/* --- SCROLLBAR PERSONALIZADO SCI-FI --- */
.sci-fi-scroll {
    scrollbar-width: thin;
    scrollbar-color: #333 rgba(255, 255, 255, 0.05);
}

.sci-fi-scroll::-webkit-scrollbar {
    width: 6px;
    height: 6px;
}

.sci-fi-scroll::-webkit-scrollbar-track {
    background: rgba(0, 0, 0, 0.3);
}

.sci-fi-scroll::-webkit-scrollbar-thumb {
    background: #444;
    border-radius: 10px;
    transition: background 0.2s;
}

.sci-fi-scroll::-webkit-scrollbar-thumb:hover {
    background: #F2D019;
}

/* --- ANIMACIONES DE ALTO RENDIMIENTO (GPU) --- */
@keyframes drift-slow {
    0% { transform: translateX(0); }
    100% { transform: translateX(-25%); }
}

@keyframes morph {
    0% { border-radius: 60% 40% 30% 70% / 60% 30% 70% 40%; }
    50% { border-radius: 30% 60% 70% 40% / 50% 60% 30% 60%; }
    100% { border-radius: 60% 40% 30% 70% / 60% 30% 70% 40%; }
}

@keyframes undulate {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-25px); }
}

@keyframes grain-flow {
    0% { transform: translate(0, 0); }
    100% { transform: translate(-5%, -5%); }
}

@keyframes scanline-move {
    0% { top: -10%; opacity: 0; }
    10% { opacity: 1; }
    90% { opacity: 1; }
    100% { top: 110%; opacity: 0; }
}

@keyframes portal-pulse {
    0%, 100% { filter: drop-shadow(0 0 15px rgba(0, 240, 255, 0.4)) brightness(1); }
    50% { filter: drop-shadow(0 0 40px rgba(0, 240, 255, 0.8)) brightness(1.2); }
}

@keyframes glitch-text {
    0% { transform: translate(0); text-shadow: 2px 2px 0px #000; }
    2% { transform: translate(-2px, 2px); text-shadow: -2px 0 cyan, 2px 0 red; }
    4% { transform: translate(2px, -1px); text-shadow: 2px 0 cyan, -2px 0 red; }
    6% { transform: translate(0); }
    100% { transform: translate(0); }
}

@keyframes energy-arc {
    0% { transform: scaleX(0) translateX(-100%); opacity: 0; }
    50% { transform: scaleX(1) translateX(0); opacity: 1; }
    100% { transform: scaleX(0) translateX(100%); opacity: 0; }
}

@keyframes float-tech {
    0%, 100% { transform: translateY(0) rotate(0deg); }
    50% { transform: translateY(-15px) rotate(5deg); }
}

/* --- NUEVAS ANIMACIONES DE INTERFAZ --- */

/* Movimiento de fondo infinito */
@keyframes bg-pan {
    0% { background-position: 0% 0%; }
    100% { background-position: 100px 100px; }
}

/* Entrada secuencial (Stagger) */
@keyframes fade-up {
    0% { opacity: 0; transform: translateY(30px); }
    100% { opacity: 1; transform: translateY(0); }
}

/* --- HINT PULSE (One Shot - Light Only) --- */
@keyframes guide-pulse {
    0% { 
        filter: brightness(1) drop-shadow(0 0 0 rgba(0,0,0,0)); 
    }
    20% { 
        filter: brightness(1.3) drop-shadow(0 0 15px rgba(0, 240, 255, 0.6)); 
    }
    40% { 
        filter: brightness(1.1) drop-shadow(0 0 5px rgba(0, 240, 255, 0.3)); 
    }
    60% { 
        filter: brightness(1.25) drop-shadow(0 0 10px rgba(0, 240, 255, 0.5)); 
    }
    100% { 
        filter: brightness(1) drop-shadow(0 0 0 rgba(0,0,0,0)); 
    }
}

.animate-portal-fx { animation: portal-pulse 3s ease-in-out infinite; }
.animate-glitch-active { animation: glitch-text 4s linear infinite; }
.animate-energy { animation: energy-arc 2s cubic-bezier(0.4, 0, 0.2, 1) infinite; }
.animate-float-tech { animation: float-tech 6s ease-in-out infinite; }

.animate-stack-entry { animation: stack-entry 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
.animate-grain { animation: grain-flow 0.5s steps(3) infinite; }
.animate-drift { animation: drift-slow 80s linear infinite; }
.animate-blob-1 { animation: morph 10s ease-in-out infinite, undulate 6s ease-in-out infinite alternate; }
.animate-blob-2 { animation: morph 14s ease-in-out infinite, undulate 8s ease-in-out infinite alternate; }
.animate-blob-3 { animation: morph 11s ease-in-out infinite, undulate 5s ease-in-out infinite alternate; }
.animate-float { animation: undulate 6s ease-in-out infinite; }
.animate-scanline { animation: scanline-move 4s linear infinite; }
.animate-dust-wander { animation: dust-wander 40s linear infinite; }

/* Utilitarios de Animación */
.animate-bg-pan { animation: bg-pan 20s linear infinite; }

.animate-fade-up { 
    opacity: 0; /* Comienza invisible */
    animation: fade-up 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards; 
}

/* Clase para activar la guia visual */
.hint-pulse {
    animation: guide-pulse 1.2s ease-out 1 forwards; /* Ejecutar una vez */
}

.delay-100 { animation-delay: 100ms; }
.delay-200 { animation-delay: 200ms; }
.delay-300 { animation-delay: 300ms; }
.delay-400 { animation-delay: 400ms; }
.delay-500 { animation-delay: 500ms; }

import React, { useEffect, useState } from 'react';
import { ASSETS } from '../../config/assets';
import { CastShadow } from '../effects/shadows/CastShadow';
import { sfx } from '../../utils/SoundManager';
import { WorldTooltip } from '../ui/WorldTooltip';
import { useImageInteraction } from '../../features/InteractionSystem';

const HERO_STYLES = `
  @keyframes hologram-entry {
    0% { opacity: 0; transform: perspective(1000px) rotateY(-30deg) translateZ(100px) scale(0.5); filter: blur(10px) brightness(3); }
    100% { opacity: 1; transform: perspective(1000px) rotateY(0deg) translateZ(0) scale(1); filter: blur(0px) brightness(1); }
  }

  .bl-hud-frame {
    position: relative;
    /* REDUCED SIZE: Making the hologram smaller relative to the portal frame */
    width: 60%; 
    height: auto;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    padding: 15px;
    border-left: 2px solid rgba(0, 240, 255, 0.5);
    background: linear-gradient(90deg, rgba(0, 240, 255, 0.05) 0%, transparent 100%);
    /* Centering is handled by parent flex, removed large margin-top */
  }

  .bl-header {
    font-family: 'Teko', sans-serif;
    /* REDUCED FONT SIZE */
    font-size: 3rem; 
    font-weight: 800;
    line-height: 0.8;
    color: #fff;
    text-transform: uppercase;
    letter-spacing: -1px;
    -webkit-text-stroke: 1px rgba(0,0,0,0.5);
    margin-bottom: 8px;
  }

  .bl-tag {
    font-family: 'Roboto Mono', monospace;
    font-size: 0.6rem;
    color: #F2D019;
    background: rgba(0,0,0,0.8);
    padding: 2px 6px;
    border: 1px solid #F2D019;
    margin-bottom: 10px;
    letter-spacing: 1.5px;
  }

  .bl-stats-container {
    display: flex;
    flex-direction: column;
    gap: 6px;
    width: 100%;
  }

  .bl-stat-row {
    display: flex;
    align-items: center;
    gap: 8px;
    width: 100%;
  }

  .bl-stat-label {
    font-family: 'Teko', sans-serif;
    font-size: 1rem; /* Smaller labels */
    width: 60px;
    color: rgba(255,255,255,0.7);
  }

  .bl-stat-bar-bg {
    height: 4px; /* Thinner bars */
    flex-grow: 1;
    background: rgba(255,255,255,0.1);
    position: relative;
    overflow: hidden;
  }

  .bl-stat-bar-fill {
    position: absolute;
    top: 0;
    left: 0;
    height: 100%;
    background: #00F0FF;
    box-shadow: 0 0 8px #00F0FF;
  }

  .bl-quote {
    margin-top: 15px;
    font-family: 'Roboto Mono', monospace;
    font-size: 0.65rem; /* Smaller quote text */
    color: #fff;
    opacity: 0.8;
    border-left: 2px solid #F2D019;
    padding-left: 8px;
    text-align: left;
    line-height: 1.2;
  }
`;

const HolographicHUD = ({ onNavigate, activeIndex }: { onNavigate: () => void, activeIndex: number }) => {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    if (activeIndex === 1) {
        setIsVisible(false);
        const timer = setTimeout(() => {
          setIsVisible(true);
        }, 300);
        return () => clearTimeout(timer);
    } else {
        setIsVisible(false);
    }
  }, [activeIndex]);

  if (!isVisible) return null;

  return (
    <>
      <style>{HERO_STYLES}</style>
      <div 
        className="absolute inset-0 flex items-center justify-center pointer-events-auto cursor-pointer z-[200]"
        style={{ animation: 'hologram-entry 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards' }}
        onClick={onNavigate}
      >
        <div className="bl-hud-frame group">
            <div className="bl-tag animate-glitch-active">LEVEL 99 SPECIALIST</div>
            <div className="bl-header group-hover:text-[#F2D019] transition-colors duration-300">
                CREATIVE<br/><span className="text-[#00F0FF]">ARCHITECT</span>
            </div>

            <div className="bl-stats-container mt-2">
                {[
                    { label: "DESIGN", val: "95%" },
                    { label: "CODE", val: "88%" },
                    { label: "AI LOGIC", val: "92%" }
                ].map((s, i) => (
                    <div key={i} className="bl-stat-row">
                        <span className="bl-stat-label">{s.label}</span>
                        <div className="bl-stat-bar-bg">
                            <div className="bl-stat-bar-fill" style={{ width: s.val }} />
                        </div>
                    </div>
                ))}
            </div>

            <div className="bl-quote">
                "Merging visual aesthetics with <br/>neural-driven performance."
            </div>

            <div className="absolute top-0 right-0 w-12 h-12 border-t-2 border-r-2 border-[#00F0FF]/30" />
            <div className="absolute bottom-0 left-0 w-full h-[1px] bg-gradient-to-r from-[#00F0FF] to-transparent opacity-50" />
        </div>
      </div>
    </>
  );
};

interface PortalProps {
    onNavigate: () => void;
    onQuestClick: () => void;
    activeIndex: number;
    shouldPulse: boolean;
}

export const Portal: React.FC<PortalProps> = ({ onNavigate, onQuestClick, activeIndex, shouldPulse }) => {
    const isActive = activeIndex === 1;
    // We keep the interaction logic mainly for the HUD container if needed
    const propsPortal = useImageInteraction("NORTH SECTOR: DATA HUB", "");
    const propsPropp = useImageInteraction("QUEST GIVER", ASSETS.PROPS.PROPP);

    // Adjusted heights - Portal frame is gone, so we manage space for the HUD
    const portalHeight = '55vh';
    const portalWidth = '400px'; 
    const charHeight = isActive ? '70vh' : '58vh';

    return (
        <div 
            className="relative inline-block pointer-events-none"
            style={{
                // Positioned roughly where it was, but relying on container dimensions not image
                transform: 'translateX(calc(-50% - 360px)) translateY(calc(10vh + 215px))', 
            }}
        >
            {/* 1. HOLOGRAPHIC CONTAINER (Replaces the Stone Portal) */}
            <div 
                className={`relative z-10 overflow-hidden pointer-events-auto ${propsPortal.className} ${shouldPulse ? 'hint-pulse' : ''}`}
                style={{ 
                    height: portalHeight,
                    width: portalWidth,
                    // Simple tech shape clip-path
                    clipPath: 'polygon(10% 0, 100% 0, 100% 90%, 90% 100%, 0 100%, 0 10%)',
                    background: 'rgba(0, 10, 20, 0.2)',
                    border: '1px solid rgba(0, 240, 255, 0.1)'
                }}
                onMouseEnter={propsPortal.onMouseEnter}
                onMouseLeave={propsPortal.onMouseLeave}
            >
                {/* Back Lighting */}
                <div className="absolute inset-0 bg-cyan-950/20 backdrop-blur-[1px]" />

                {/* Grid Effect */}
                <div 
                    className="absolute inset-0 opacity-[0.15]" 
                    style={{ 
                        backgroundImage: `linear-gradient(rgba(0, 240, 255, 0.3) 1px, transparent 1px), linear-gradient(90deg, rgba(0, 240, 255, 0.3) 1px, transparent 1px)`,
                        backgroundSize: '40px 40px'
                    }} 
                />

                {/* Scanline */}
                <div className="absolute left-0 w-full h-[15%] bg-gradient-to-b from-transparent via-[#00F0FF]/20 to-transparent animate-scanline blur-md z-20 pointer-events-none" />

                {/* The HUD Content */}
                <HolographicHUD onNavigate={onNavigate} activeIndex={activeIndex} />
            </div>

            {/* 2. Quest Giver / Character (Positioned relative to the container) */}
            <div className={`absolute left-0 bottom-0 z-[100] flex items-end justify-center pointer-events-auto cursor-pointer group ${shouldPulse ? 'hint-pulse' : ''}`}
                 style={{ 
                     animationDelay: '0.2s',
                     transform: 'translateX(calc(-50% + 60px)) translateY(calc(10vh + 175px))',
                     filter: 'none'
                 }}
                 onClick={onQuestClick}
                 onMouseEnter={propsPropp.onMouseEnter}
                 onMouseLeave={propsPropp.onMouseLeave}
            >
                <CastShadow
                    shadowSrc={ASSETS.PROPS.PROPP}
                    debugId="PROPP"
                    height={charHeight}
                    initialConfig={{ perspective: 1140, rotateX: 44, skewX: -9, scaleY: 1.33, x: -20, y: 14, blur: 1.5, opacity: 0.8 }}
                >
                    <div className="relative">
                        <img 
                            src={ASSETS.PROPS.PROPP} 
                            alt="QUEST GIVER" 
                            className={`object-contain object-bottom select-none brightness-100 ${propsPropp.className}`}
                            style={{ height: charHeight }} 
                        />
                    </div>
                </CastShadow>
                <WorldTooltip title="QUESTS" subtitle="PROJECT LOG" side="right" className="!bottom-[80%]" />
            </div>
        </div>
    );
};

import React, { useEffect, useRef } from 'react';

interface EchoPortalProps {
    trigger?: boolean;
}

export const EchoPortal: React.FC<EchoPortalProps> = ({ trigger = false }) => {
    const laserRef = useRef<HTMLDivElement>(null);
    const titlesRef = useRef<HTMLElement>(null);
    const bannerRef = useRef<HTMLDivElement>(null);
    const paragraphRef = useRef<HTMLDivElement>(null);
    const statsRef = useRef<HTMLElement>(null);

    useEffect(() => {
        const refs = [laserRef, titlesRef, bannerRef, paragraphRef, statsRef];

        // Limpiar clases al desmontar o reiniciar
        const reset = () => {
            refs.forEach(ref => {
                if (ref.current) ref.current.classList.remove('active');
            });
        };

        if (trigger) {
            reset();

            const sequence = [
                { ref: laserRef, delay: 100 },
                { ref: titlesRef, delay: 500 },
                { ref: bannerRef, delay: 1100 },
                { ref: paragraphRef, delay: 1600 },
                { ref: statsRef, delay: 2000 }
            ];

            const timeouts: ReturnType<typeof setTimeout>[] = [];

            sequence.forEach(item => {
                const t = setTimeout(() => {
                    if (item.ref.current) {
                        item.ref.current.classList.add('active');
                    }
                }, item.delay);
                timeouts.push(t);
            });

            return () => timeouts.forEach(clearTimeout);
        } else {
            reset();
        }
    }, [trigger]);

    return (
        <div className="relative w-[44vh] aspect-[2/3] md:w-[58vh] pointer-events-auto cursor-pointer group echo-portal-root">
            <style>{`
                /* =========================================
                   SCOPED CONFIG & VARIABLES
                   ========================================= */
                .echo-portal-root {
                    --yellow: #facc15;
                    --teal: #2DD4BF;
                    --red: #ef4444;
                    --hazard-gradient: repeating-linear-gradient(-45deg, #000, #000 10px, var(--yellow) 10px, var(--yellow) 20px);
                    --hex-svg: url("data:image/svg+xml,%3Csvg width='56' height='100' viewBox='0 0 56 100' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M28 66L0 50L0 16L28 0L56 16L56 50L28 66L28 100' fill='none' stroke='%232DD4BF' stroke-width='1.5' stroke-opacity='0.5'/%3E%3Cpath d='M28 0L28 33' fill='none' stroke='%2300FFF0' stroke-width='1' stroke-opacity='0.4'/%3E%3C/svg%3E");
                    --card-inset: 3%;
                    --transition-snappy: cubic-bezier(0.25, 0.46, 0.45, 0.94);
                    --transition-bouncy: cubic-bezier(0.175, 0.885, 0.32, 1.275);
                }

                /* =========================================
                   ANIMATIONS
                   ========================================= */
                @keyframes laser-scan {
                    0% { top: 0%; opacity: 0; }
                    20%, 80% { opacity: 1; }
                    100% { top: 100%; opacity: 0; }
                }

                @keyframes shine-reflect {
                    0%, 90% { background-position: -200% 0; }
                    100% { background-position: 200% 0; }
                }

                @keyframes atlas-unfold {
                    0% { transform: scale(0.2) rotateY(90deg); filter: brightness(10) blur(20px); opacity: 0; }
                    60% { transform: scale(1.1) rotateY(-5deg); filter: brightness(2) blur(2px); opacity: 1; } 
                    100% { transform: scale(1) rotateY(0deg); filter: brightness(1.1); opacity: 1; }
                }

                @keyframes banner-reveal {
                    from { transform: scaleX(0); opacity: 0; }
                    to { transform: scaleX(1); opacity: 1; }
                }

                @keyframes element-pop {
                    from { transform: scale(0.8) translateY(30px); opacity: 0; }
                    to { transform: scale(1) translateY(0); opacity: 1; }
                }

                @keyframes holo-flicker {
                    0%, 100% { opacity: 0.9; }
                    33% { opacity: 0.85; }
                    66% { opacity: 0.95; }
                }

                @keyframes hazard-scroll {
                    to { background-position: 28px 0; }
                }

                @keyframes hex-drift {
                    0% { background-position: 0 0; }
                    100% { background-position: 56px 100px; }
                }

                @keyframes hex-drift-reverse {
                    0% { background-position: 56px 100px; }
                    100% { background-position: 0 0; }
                }

                @keyframes hex-color-cycle {
                    0%, 100% { filter: hue-rotate(0deg) brightness(1); }
                    20% { filter: hue-rotate(45deg) brightness(1.2); }
                    40% { filter: hue-rotate(90deg) brightness(1.1); }
                    60% { filter: hue-rotate(180deg) brightness(1.3); }
                    80% { filter: hue-rotate(270deg) brightness(1.15); }
                }

                @keyframes border-glow-pulse {
                    0%, 100% { box-shadow: 0 20px 40px rgba(0, 0, 0, 0.8), 0 0 30px rgba(250, 204, 21, 0.3), inset 0 0 20px rgba(250, 204, 21, 0.05); }
                    50% { box-shadow: 0 25px 50px rgba(0, 0, 0, 0.9), 0 0 50px rgba(250, 204, 21, 0.5), 0 0 80px rgba(250, 204, 21, 0.2), inset 0 0 30px rgba(250, 204, 21, 0.1); }
                }

                @keyframes scanline-sweep {
                    0% { top: -2px; opacity: 0; }
                    10% { opacity: 1; }
                    90% { opacity: 1; }
                    100% { top: calc(100% + 2px); opacity: 0; }
                }

                @keyframes shimmer-effect {
                    0% { background-position: -200% 0; }
                    100% { background-position: 200% 0; }
                }

                @keyframes value-glow {
                    0%, 100% { text-shadow: 0 0 30px rgba(45, 212, 191, 0.6); }
                    50% { text-shadow: 0 0 50px rgba(45, 212, 191, 1), 0 0 80px rgba(45, 212, 191, 0.5); }
                }

                @keyframes tag-bounce {
                    0%, 100% { transform: translateY(0) scaleX(1); }
                    25% { transform: translateY(-4px) scaleX(1.1); }
                    50% { transform: translateY(-2px) scaleX(1.05); }
                }

                @keyframes energy-ring {
                    0% { transform: scale(0.95); opacity: 0.5; }
                    50% { transform: scale(1.02); opacity: 0.8; }
                    100% { transform: scale(0.95); opacity: 0.5; }
                }

                /* =========================================
                   STRUCTURE
                   ========================================= */
                .scene {
                    width: 100%; height: 100%; position: relative;
                    display: flex; justify-content: center; align-items: center;
                    container-type: size; perspective: 1200px;
                }

                .card {
                    position: absolute; inset: var(--card-inset);
                    background: radial-gradient(circle at center, rgba(15, 45, 55, 0.5) 0%, rgba(5, 15, 20, 0.98) 100%);
                    backdrop-filter: blur(10px);
                    border: 1.5px solid rgba(45, 212, 191, 0.6);
                    border-radius: 1.5cqw;
                    z-index: 10; overflow: hidden;
                    box-shadow: inset 0 0 60px rgba(45, 212, 191, 0.15), 0 0 40px rgba(0, 0, 0, 0.7);
                }

                .card::before {
                    content: ""; position: absolute; inset: 0;
                    background: var(--hex-svg) 0 0 / 28px 50px; opacity: 0.7;
                    mask-image: radial-gradient(circle at center, black 70%, transparent 100%);
                    animation: hex-drift 8s linear infinite, hex-color-cycle 12s ease-in-out infinite;
                    z-index: 1; /* Lowest background layer */
                }

                .card::after {
                    content: ""; position: absolute; inset: 0;
                    background: var(--hex-svg) 14px 25px / 35px 62px; opacity: 0.35;
                    mask-image: radial-gradient(circle at center, black 50%, transparent 90%);
                    animation: hex-drift-reverse 12s linear infinite, hex-color-cycle 8s ease-in-out infinite reverse;
                    mix-blend-mode: screen; pointer-events: none;
                    z-index: 2;
                }

                .laser {
                    position: absolute; inset: 0 0 auto 0; height: 1.2cqw;
                    background: var(--teal); box-shadow: 0 0 3cqw var(--teal), 0 0 6cqw var(--teal);
                    z-index: 40; opacity: 0;
                }
                .laser.active { animation: laser-scan 0.8s ease-in-out forwards; }

                .hologram-wrapper {
                    position: absolute; 
                    top: 50%; left: 50%;
                    transform: translate(-50%, -50%); 
                    width: 75%; height: 90%; /* Adjusted sizing */
                    z-index: 20; /* Higher than card bg (z:10 + 2), lower than UI (z:30) */
                    pointer-events: none;
                    animation: holo-flicker 4s infinite;
                    display: flex; justify-content: center; align-items: center;
                }

                .hologram-wrapper::after {
                    content: ""; position: absolute; inset: 0;
                    background: var(--hex-svg) 0 0 / 14px 24px; opacity: 0.3; /* Reduced opacity */
                    mask-image: linear-gradient(to bottom, transparent, black 10%, black 90%, transparent);
                    mix-blend-mode: overlay; pointer-events: none;
                }

                .img { 
                    height: 100%; width: auto; 
                    filter: drop-shadow(0 0 20px rgba(0,0,0,0.8)); 
                    object-fit: contain; 
                    position: relative; z-index: 5;
                }

                /* =========================================
                   UI SYSTEMS
                   ========================================= */
                .ui-echo {
                    position: absolute; inset: var(--card-inset); z-index: 30;
                    display: flex; flex-direction: column; align-items: center;
                    padding: 2cqw 0 12cqw; transform-style: preserve-3d;
                }

                .txt-container {
                    width: 100%; opacity: 0; display: flex; flex-direction: column;
                    align-items: center; transform-origin: center center;
                    will-change: transform, opacity, filter; z-index: 50;
                    transform-style: preserve-3d; perspective: 1000px; cursor: pointer;
                    transition: transform 0.5s cubic-bezier(0.34, 1.56, 0.64, 1), filter 0.4s ease;
                }
