interface PortalProps {
    onNavigate: () => void;
    onQuestClick: () => void;
    activeIndex: number;
    shouldPulse: boolean;
}

export const Portal: React.FC<PortalProps> = ({ onQuestClick, activeIndex, shouldPulse }) => {
    const isActive = activeIndex === 1;
    const propsPropp = useImageInteraction("QUEST GIVER", ASSETS.PROPS.PROPP);

    // Altura dinámica basada en el estado activo
    const charHeight = isActive ? '70vh' : '58vh';

    return (
        <div 
            className="relative inline-block pointer-events-none"
            style={{
                // Mantenemos la posición base del contenedor para que el personaje no se mueva de su sitio original
                transform: 'translateX(calc(-50% - 360px)) translateY(calc(10vh + 215px))', 
            }}
        >
            {/* Quest Giver / Character (Elemento original solicitado) */}
            <div className={`absolute left-0 bottom-0 z-[100] flex items-end justify-center pointer-events-auto cursor-pointer group ${shouldPulse ? 'hint-pulse' : ''}`}
                 style={{ 
                     animationDelay: '0.2s',
                     // Ajuste fino de posición relativo al contenedor padre
                     transform: 'translateX(calc(-50% + 60px)) translateY(calc(10vh + 175px))',
                     filter: 'none'
                 }}
                 onClick={onQuestClick}
                 onMouseEnter={propsPropp.onMouseEnter}
                 onMouseLeave={propsPropp.onMouseLeave}
            >
                <CastShadow
                    shadowSrc={ASSETS.PROPS.PROPP}
                    debugId="PROPP"
                    height={charHeight}
                    initialConfig={{ perspective: 1140, rotateX: 44, skewX: -9, scaleY: 1.33, x: -20, y: 14, blur: 1.5, opacity: 0.8 }}
                >
                    <div className="relative">
                        <img 
                            src={ASSETS.PROPS.PROPP} 
                            alt="QUEST GIVER" 
                            className={`object-contain object-bottom select-none brightness-100 ${propsPropp.className}`}
                            style={{ height: charHeight }} 
                        />
                    </div>
                </CastShadow>

                {/* Tooltip informativo */}
                <WorldTooltip title="QUESTS" subtitle="PROJECT LOG" side="right" className="!bottom-[80%]" />
            </div>
        </div>
    );
};

