// Helper hook for one-time animation trigger
const useZoneHint = (activeIndex: number, zoneIndex: number) => {
    const [pulse, setPulse] = useState(false);
    const hasTriggeredRef = useRef(false);

    useEffect(() => {
        if (activeIndex === zoneIndex && !hasTriggeredRef.current) {
            hasTriggeredRef.current = true;
            // Small delay to ensure the user has settled into the view
            const t = setTimeout(() => {
                setPulse(true);
                // Remove class after animation completes (1.2s)
                setTimeout(() => setPulse(false), 1200);
            }, 500);
            return () => clearTimeout(t);
        }
    }, [activeIndex, zoneIndex]);

    return pulse;
};

