export const Blender3D: React.FC = () => {
    return (
        <GenericIcon3D
            config={{
                boxColor: '#262626',
                lightDir: new THREE.Vector3(0.3, 0.5, 1.0).normalize(),
                hatchingDensity: 12.0,
                hatchingStrength: 0.3,
                outlineWidth: 0.03
            }}
            onBuildContent={(contentGroup, getMat, outMat) => {
                // --- SVG LOADING LOGIC ---
                const loader = new SVGLoader();
                const svgData = loader.parse(SVG_CONTENT);
                const tempGroup = new THREE.Group();
                let maxShapeSize = 0;

                // 1. Calculate Bounds
                svgData.paths.forEach((path) => {
                    const shapes = SVGLoader.createShapes(path);
                    shapes.forEach(shape => {
                        shape.getPoints().forEach(p => {
                            if (Math.abs(p.x) > maxShapeSize) maxShapeSize = Math.abs(p.x);
                            if (Math.abs(p.y) > maxShapeSize) maxShapeSize = Math.abs(p.y);
                        });
                    });
                });

                const dynamicDepth = maxShapeSize * 0.1;
                const bevelThickness = dynamicDepth * 0.05;

                // 2. Extrude & Color
                svgData.paths.forEach((path) => {
                    const shapes = SVGLoader.createShapes(path);
                    const fillColor = path.userData.style.fill;

                    let matColor = '#ea7600'; // Blender Orange
                    let isEye = false;

                    if (fillColor && (String(fillColor).includes('265787'))) {
                        matColor = '#2361a0'; // Blender Blue
                        isEye = true;
                    }

                    const material = getMat(matColor);

                    shapes.forEach((shape) => {
                        const geometry = new THREE.ExtrudeGeometry(shape, {
                            depth: dynamicDepth, 
                            bevelEnabled: true, 
                            bevelThickness, 
                            bevelSize: bevelThickness * 0.5, 
                            bevelSegments: 6, 
                            curveSegments: 48
                        });

                        const mesh = new THREE.Mesh(geometry, material);
                        mesh.scale.y = -1; // Flip Y for SVG

                        // Push the blue eye slightly forward
                        if (isEye) mesh.position.z = dynamicDepth * 0.1;

                        // Add Outline
                        const outlineMesh = new THREE.Mesh(geometry, outMat.clone());
                        mesh.add(outlineMesh);

                        tempGroup.add(mesh);
                    });
                });

                // 3. Center and Add to Scene
                const boxBounds = new THREE.Box3().setFromObject(tempGroup);
                const center = new THREE.Vector3();
                boxBounds.getCenter(center);
                const size = new THREE.Vector3();
                boxBounds.getSize(size);

                const logoGroup = new THREE.Group();
                // Move children to center
                for (let i = tempGroup.children.length - 1; i >= 0; i--) {
                    const child = tempGroup.children[i];
                    child.position.x -= center.x;
                    child.position.y -= center.y;
                    logoGroup.add(child);
                }

                // Scale to fit nicely in the box
                const scaleFactor = (2.5 * 0.65) / Math.max(size.x, size.y);
                logoGroup.scale.set(scaleFactor, scaleFactor, scaleFactor);
                logoGroup.position.z = 0.30; // Push forward from box face

                contentGroup.add(logoGroup);
            }}
        />
    );
};

import React from 'react';
import * as THREE from 'three';
import * as BufferGeometryUtils from 'three/addons/utils/BufferGeometryUtils.js';
import { GenericIcon3D } from './core/GenericIcon3D';

export const Figma3D: React.FC = () => {
    return (
        <GenericIcon3D
            config={{
                boxColor: '#1e1e1e',
                outlineWidth: 0.04,
                lightDir: new THREE.Vector3(1.0, 1.0, 1.0).normalize(),
                hatchingDensity: 10.0,
                hatchingStrength: 0.2
            }}
            onBuildContent={(contentGroup, getMat, outMat) => {
                const figmaGroup = new THREE.Group();

                const s = 0.5; 
                const cellRadius = s / 2; 
                const extrudeSettings = { 
                    depth: 0.15, 
                    bevelEnabled: true, 
                    bevelThickness: 0.015, 
                    bevelSize: 0.01, 
                    bevelSegments: 3, 
                    curveSegments: 64 
                };

                const colors = {
                    red: '#F24E1E', 
                    orange: '#FF7262', 
                    purple: '#A259FF', 
                    blue: '#1ABCFE', 
                    green: '#0ACF83'
                };

                function createPart(type: string, color: string, x: number, y: number) {
                    const shape = new THREE.Shape();
                    if (type === 'circle') shape.absarc(0, 0, cellRadius, 0, Math.PI * 2, false);
                    else if (type === 'semicircle-left') { 
                        shape.moveTo(0, -cellRadius); 
                        shape.lineTo(cellRadius, -cellRadius); 
                        shape.lineTo(cellRadius, cellRadius); 
                        shape.absarc(0, 0, cellRadius, Math.PI/2, Math.PI * 1.5, false); 
                    }
                    else if (type === 'semicircle-right') { 
                        shape.moveTo(0, cellRadius); 
                        shape.lineTo(-cellRadius, cellRadius); 
                        shape.lineTo(-cellRadius, -cellRadius); 
                        shape.absarc(0, 0, cellRadius, -Math.PI/2, Math.PI/2, false); 
                    }
                    else if (type === 'teardrop-figma') { 
                        shape.moveTo(cellRadius, 0); 
                        shape.lineTo(cellRadius, cellRadius); 
                        shape.lineTo(0, cellRadius); 
                        shape.absarc(0, 0, cellRadius, Math.PI/2, Math.PI*2, false); 
                    }

                    const sharpGeo = new THREE.ExtrudeGeometry(shape, extrudeSettings);
                    const mesh = new THREE.Mesh(sharpGeo, getMat(color));
                    mesh.position.set(x, y, 0.3);

                    // Create smoother outline
                    let outlineGeo = sharpGeo.clone();
                    outlineGeo = BufferGeometryUtils.mergeVertices(outlineGeo, 0.001);
                    outlineGeo.computeVertexNormals();

                    const outlineMesh = new THREE.Mesh(outlineGeo, outMat.clone());
                    // @ts-ignore
                    outlineMesh.material.uniforms.uT.value = 0.04 * 0.5; // Thinner outline for internal parts
                    outlineMesh.renderOrder = -1;
                    mesh.add(outlineMesh);

                    return mesh;
                }

                const xL = -s/2; 
                const xR = s/2; 
                const yTop = s; 
                const yMid = 0; 
                const yBot = -s; 

                figmaGroup.add(createPart('semicircle-left', colors.red, xL, yTop));
                figmaGroup.add(createPart('semicircle-right', colors.orange, xR, yTop));
                figmaGroup.add(createPart('semicircle-left', colors.purple, xL, yMid));
                figmaGroup.add(createPart('circle', colors.blue, xR, yMid));
                figmaGroup.add(createPart('teardrop-figma', colors.green, xL, yBot));

                contentGroup.add(figmaGroup);
            }}
        />
    );
};

import React from 'react';
import * as THREE from 'three';
import { FontLoader } from 'three/addons/loaders/FontLoader.js';
import { TextGeometry } from 'three/addons/geometries/TextGeometry.js';
import * as BufferGeometryUtils from 'three/addons/utils/BufferGeometryUtils.js';
