export const Audition3D: React.FC = () => {
    return (
        <GenericIcon3D
            config={{
                boxColor: '#00e4bd',
                lightDir: new THREE.Vector3(0.8, 0.8, 1.0).normalize(),
                outlineWidth: 0.03
            }}
            onBuildContent={(contentGroup, getMat, outMat) => {
                const loader = new FontLoader();

                // Using helper function logic from GenericIcon3D structure implicitly via closure
                loader.load('https://cdn.jsdelivr.net/npm/three@0.128.0/examples/fonts/helvetiker_bold.typeface.json', function (font) {
                    const textGeo = new TextGeometry('Au', { 
                        font: font, 
                        size: 1.2, 
                        height: 0.1, 
                        curveSegments: 8, 
                        bevelEnabled: true, 
                        bevelThickness: 0.05, 
                        bevelSize: 0.03, 
                        bevelOffset: 0, 
                        bevelSegments: 5 
                    });

                    textGeo.center();

                    const smoothTextGeo = BufferGeometryUtils.mergeVertices(textGeo, 0.001);
                    smoothTextGeo.computeVertexNormals();

                    const textMesh = new THREE.Mesh(textGeo, getMat('#002e26'));
                    textMesh.position.z = 0.3; 
                    textMesh.position.y = 0.1;

                    const textOutline = new THREE.Mesh(smoothTextGeo, outMat.clone());
                    // @ts-ignore
                    textOutline.material.uniforms.uT.value = 0.03 * 0.5;
                    textMesh.add(textOutline);

                    contentGroup.add(textMesh);
                });
            }}
        />
    );
};

import React from 'react';
import * as THREE from 'three';
import { SVGLoader } from 'three/addons/loaders/SVGLoader.js';
import * as BufferGeometryUtils from 'three/addons/utils/BufferGeometryUtils.js';
import { GenericIcon3D, GenericIconConfig } from './core/GenericIcon3D';

export interface IconConfig extends GenericIconConfig {
    logoColor: string;
    accentColor?: string;
    logoColorRef?: string;
    accentColorRef?: string;
    boxColorRef?: string; // Color to ignore in SVG (bg rect)

    isVectorLike?: boolean; // Unused in new logic but kept for interface compat
    logoScale?: number;
    depth?: number;
}

interface StandardIcon3DProps {
    svgContent: string;
    config: IconConfig;
}

export const StandardIcon3D: React.FC<StandardIcon3DProps> = ({ svgContent, config }) => {
    return (
        <GenericIcon3D
            config={config}
            onBuildContent={(contentGroup, getMat, outMat) => {
                const loader = new SVGLoader();
                const svgData = loader.parse(svgContent);
                const logoGroup = new THREE.Group();

                // 1. Calculate Bounds for Centering
                let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
                svgData.paths.forEach((path) => {
                    const shapes = SVGLoader.createShapes(path);
                    shapes.forEach(shape => {
                       shape.getPoints().forEach(p => {
                           if(p.x < minX) minX = p.x; if(p.x > maxX) maxX = p.x;
                           if(p.y < minY) minY = p.y; if(p.y > maxY) maxY = p.y;
                       });
                    });
                });

                const centerX = (minX + maxX) / 2;
                const centerY = (minY + maxY) / 2;
                const scale = config.logoScale || 0.012; 

                // 2. Group Geometries by Color to optimize Draw Calls
                const geometriesByColor: Record<string, THREE.BufferGeometry[]> = {};

                svgData.paths.forEach((path) => {
                     const shapes = SVGLoader.createShapes(path);
                     const fillColor = path.userData.style.fill;

                     let useColor = config.logoColor;

                     // Filter out Background Boxes (the big square rects in icons)
                     if (config.boxColorRef && fillColor && fillColor.toLowerCase() === config.boxColorRef.toLowerCase()) return;
                     if (fillColor && (fillColor.toLowerCase() === '#001e36' || fillColor.toLowerCase() === '#330000')) return;

                     // Determine Color (Main or Accent)
                     if (config.accentColor && config.accentColorRef && fillColor && fillColor.toLowerCase() === config.accentColorRef.toLowerCase()) {
                         useColor = config.accentColor;
                     }

                     if (!geometriesByColor[useColor]) {
                         geometriesByColor[useColor] = [];
                     }

                     shapes.forEach((shape) => {
                         const depth = config.depth || 15;
                         const geometry = new THREE.ExtrudeGeometry(shape, { 
                             depth, 
                             bevelEnabled: true, 
                             bevelThickness: 2, 
                             bevelSize: 1, 
                             bevelSegments: 3 
                         });

                         // Pre-Apply Transforms (Scale & Center)
                         geometry.scale(scale, -scale, scale);
                         geometry.translate(-centerX * scale, centerY * scale, 0);

                         geometriesByColor[useColor].push(geometry);
                     });
                });

                // 3. Merge & Create Meshes
                Object.keys(geometriesByColor).forEach(colorKey => {
                    const geometries = geometriesByColor[colorKey];
                    if (geometries.length === 0) return;

                    const mergedGeometry = BufferGeometryUtils.mergeGeometries(geometries);
                    geometries.forEach(g => g.dispose()); // Cleanup

                    if (mergedGeometry) {
                        mergedGeometry.computeVertexNormals(); 

                        const mesh = new THREE.Mesh(mergedGeometry, getMat(colorKey));

                        const outlineMesh = new THREE.Mesh(mergedGeometry, outMat.clone());
                        // @ts-ignore
                        outlineMesh.material.uniforms.uT.value = (config.outlineWidth || 0.035) * 0.3;
                        mesh.add(outlineMesh);

                        logoGroup.add(mesh);
                    }
                });

                // 4. Final Centering Adjustment
                const bbox = new THREE.Box3().setFromObject(logoGroup);
                const center = new THREE.Vector3();
                bbox.getCenter(center);
                logoGroup.position.sub(center);
                logoGroup.position.z += 0.2; // Push slightly forward from center

                // 5. Apply Global Scale to fit the generic box
                logoGroup.scale.setScalar(1.5);

                contentGroup.add(logoGroup);
            }}
        />
    );
};

import React, { useEffect, useRef, useState } from 'react';
import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';
import { createMangaMaterial, createOutlineMaterial } from './SharedMangaMaterial';

export interface GenericIconConfig {
    // Apariencia Base
    boxColor: string;
    shadowColor?: string;
    outlineColor?: string;
    outlineWidth?: number;

    // Configuración Shaders (Manga Style)
    lightDir?: THREE.Vector3;
    hatchingDensity?: number;
    hatchingStrength?: number;
    shadowLimit?: number;
    specularLimit?: number;

    // Animación
    spinSpeed?: number;
    floatSpeed?: number;
    floatAmp?: number;
    springStiffness?: number;
    springDamping?: number;

    // Interacción
    interactive?: boolean;
}

interface GenericIcon3DProps {
    config: GenericIconConfig;
    /** 
     * Función callback para construir el contenido específico del icono (Logos, Texto, Formas).
     * Se llama una sola vez al montar la escena.
     * @param contentGroup El grupo THREE.js que rotará y rebotará. Agrega tus meshes aquí.
     * @param materials Factory helper para reusar materiales Manga.
     */
    onBuildContent: (
        contentGroup: THREE.Group, 
        materialFactory: (color: string) => THREE.ShaderMaterial,
        outlineMaterial: THREE.ShaderMaterial
    ) => void | Promise<void>;
}

export const GenericIcon3D: React.FC<GenericIcon3DProps> = ({ config, onBuildContent }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        if (!containerRef.current) return;

        // --- 1. DEFAULT CONFIGURATION ---
        const defaults = {
            outlineColor: '#000000',
            outlineWidth: 0.035,
            lightDir: new THREE.Vector3(0.5, 0.5, 1.2).normalize(),
            hatchingDensity: 14.0,
            hatchingStrength: 0.1,
            shadowLimit: 0.4,
            specularLimit: 0.7,
            spinSpeed: 0.1,
            floatSpeed: 0.002,
            floatAmp: 0.1,
            springStiffness: 0.12,
            springDamping: 0.82,
            interactive: true
        };
        const cfg = { ...defaults, ...config };

        // --- 2. SCENE SETUP ---
        const width = containerRef.current.clientWidth;
        const height = containerRef.current.clientHeight;
        const scene = new THREE.Scene();

        const camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 1000);
        camera.position.set(0, 0, 8);

        const renderer = new THREE.WebGLRenderer({ 
            antialias: true, 
            alpha: true,
            powerPreference: 'high-performance' 
        });
        renderer.setSize(width, height);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        containerRef.current.appendChild(renderer.domElement);

        // --- 3. HIERARCHY SETUP ---
        const floatGroup = new THREE.Group();
        const bounceGroup = new THREE.Group();
        const spinGroup = new THREE.Group();
        const iconMeshGroup = new THREE.Group(); // El contenido real va aquí

        scene.add(floatGroup);
        floatGroup.add(bounceGroup);
        bounceGroup.add(spinGroup);
        spinGroup.add(iconMeshGroup);

        // --- 4. SHARED MATERIALS & BOX ---
        const materialCache = new Map<string, THREE.ShaderMaterial>();
        const getMat = (color: string) => {
            if (!materialCache.has(color)) {
                materialCache.set(color, createMangaMaterial({
                    color,
                    lightDir: cfg.lightDir,
                    hatchingDensity: cfg.hatchingDensity,
                    hatchingStrength: cfg.hatchingStrength,
                    shadowLimit: cfg.shadowLimit,
                    specularLimit: cfg.specularLimit
                }));
            }
            return materialCache.get(color)!;
        };

        const outMat = createOutlineMaterial(cfg.outlineColor, cfg.outlineWidth);

        // Background Box
        const boxGeo = new RoundedBoxGeometry(2.5, 2.5, 0.5, 8, 0.4);
        const boxMesh = new THREE.Mesh(boxGeo, getMat(config.boxColor));
        const boxOutline = new THREE.Mesh(boxGeo, outMat);
        boxMesh.add(boxOutline);

        // Add box directly to icon group so it moves with everything
        iconMeshGroup.add(boxMesh);

        // --- 5. BUILD CONTENT (DELEGATE) ---
        // Ejecutamos la lógica específica del icono (SVG, Texto, Formas custom)
        Promise.resolve(onBuildContent(iconMeshGroup, getMat, outMat)).then(() => {
            setIsLoading(false);
        });

        // --- 6. ANIMATION LOOP & INTERACTION ---
        let time = 0;
        let animationId: number;

        // Estado de animación física
        let currentScale = 1;
        let scaleVel = 0;
        let isDragging = false;
        let targetRotX = 0;
        let targetRotY = 0;
        let lastSpinTime = 0;
        let targetSpinY = 0;
        let currentSpinY = 0;

        const raycaster = new THREE.Raycaster();
        const mouse = new THREE.Vector2(-100, -100); // Fuera de pantalla inicialmente

        const handleMouseMove = (e: MouseEvent) => {
            if (!containerRef.current) return;
            const rect = containerRef.current.getBoundingClientRect();
            mouse.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
            mouse.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;

            if (isDragging && cfg.interactive) {
                targetRotY = mouse.x * 0.8;
                targetRotX = -mouse.y * 0.8;
            }
        };

        const checkIntersection = () => {
            raycaster.setFromCamera(mouse, camera);
            // Intersectamos boxMesh porque es el elemento más grande y fácil de "atinar"
            return raycaster.intersectObject(boxMesh).length > 0;
        };

        const handleMouseDown = () => {
            if (!cfg.interactive) return;
            if (checkIntersection()) {
                isDragging = true;
                currentScale = 0.85; // Efecto de presión
                document.body.style.cursor = 'grabbing';
            }
        };

        const handleMouseUp = () => {
            isDragging = false;
            document.body.style.cursor = 'default';
        };

        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mousedown', handleMouseDown);
        window.addEventListener('mouseup', handleMouseUp);

        const animate = () => {
            animationId = requestAnimationFrame(animate);
            time++;

            // Auto Spin Logic (Si el mouse pasa por encima pero no arrastra)
            if (!isDragging && cfg.interactive && checkIntersection()) {
                const now = Date.now();
                // Cooldown de 3 segundos entre giros rápidos
                if (now - lastSpinTime > 3000) {
                    targetSpinY += Math.PI * 2;
                    lastSpinTime = now;
                }
            }

            // Física de Rotación Continua (Spin)
            currentSpinY += (targetSpinY - currentSpinY) * cfg.spinSpeed;
            spinGroup.rotation.y = currentSpinY;

            // Física de Inclinación (Tilt)
            if (isDragging) {
                iconMeshGroup.rotation.x += (targetRotX - iconMeshGroup.rotation.x) * 0.2;
                iconMeshGroup.rotation.y += (targetRotY - iconMeshGroup.rotation.y) * 0.2;
            } else {
                // Volver a posición neutral suavemente
                iconMeshGroup.rotation.x += (0 - iconMeshGroup.rotation.x) * 0.1;
                iconMeshGroup.rotation.y += (0 - iconMeshGroup.rotation.y) * 0.1;
            }

            // Física de Rebote (Spring Scale)
            scaleVel += (1 - currentScale) * cfg.springStiffness;
            scaleVel *= cfg.springDamping;
            currentScale += scaleVel;
            bounceGroup.scale.set(currentScale, currentScale, currentScale);

            // Flotación Ambiental (Idle)
            floatGroup.position.y = Math.sin(time * cfg.floatSpeed) * cfg.floatAmp;

            renderer.render(scene, camera);
        };
        animate();

        // --- 7. CLEANUP ---
        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mousedown', handleMouseDown);
            window.removeEventListener('mouseup', handleMouseUp);
            cancelAnimationFrame(animationId);

            if (containerRef.current && renderer.domElement) {
                containerRef.current.removeChild(renderer.domElement);
            }

            renderer.dispose();
            boxGeo.dispose();
            materialCache.forEach(m => m.dispose());
            outMat.dispose();
        };
    }, [config]);

    return (
        <div ref={containerRef} className="w-full h-full relative">
            {isLoading && (
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-50">
                    <div className="w-8 h-8 border-2 border-t-white border-transparent rounded-full animate-spin"></div>
                </div>
            )}
        </div>
    );
};

import React, { useMemo, useState, useEffect } from 'react';
import { ThreeIconViewer } from '../ThreeIconViewer'; // 3dsmax (Custom Particle Logic)
import { Blender3D } from './Blender3D'; // Custom Geometry Logic
import { Figma3D } from './Figma3D'; // Custom Constructed Geometry
import { Audition3D } from './Audition3D'; // Text Geometry Logic
import { StandardIcon3D, IconConfig } from './StandardIcon3D';
import { SVG_ASSETS } from './assets/IconAssets';

interface Visualizer3DProps {
    itemId: string;
}

export const Visualizer3D: React.FC<Visualizer3DProps> = React.memo(({ itemId }) => {
    // State to track the ID that is currently allowed to be rendered.
    // If renderedId is null or doesn't match itemId, we show the placeholder.
    const [renderedId, setRenderedId] = useState<string | null>(null);

    useEffect(() => {
        // 1. AGGRESSIVE UNMOUNT
        // Immediately clear the current 3D view when the prop changes.
        // This forces React to unmount the previous 3D component, triggering its 
        // cleanup (renderer.dispose(), geometry.dispose()) BEFORE starting the new timer.
        setRenderedId(null);

        // 2. EXTENDED DEBOUNCE
        // We wait 450ms. If the user moves the mouse again within this window,
        // this timer is cleared and the component never mounts.
        // This prevents creating heavy WebGL contexts during rapid hovering.
        const timer = setTimeout(() => {
            setRenderedId(itemId);
        }, 450);

        return () => clearTimeout(timer);
    }, [itemId]);

    // Compute config only for the item we are ABOUT to render
    const standardConfig = useMemo((): { svg: string, config: IconConfig } | null => {
        // Use renderedId here to prevent calculation for items we skipped
        const targetId = renderedId; 
        if (!targetId) return null;

        switch (targetId) {
            case 'ps': return {
                svg: SVG_ASSETS.PHOTOSHOP,
                config: { boxColor: '#001e36', shadowColor: '#001020', logoColor: '#31a8ff', boxColorRef: '#001e36' }
            };
            case 'xd': return { 
                svg: SVG_ASSETS.ADOBE_XD, 
                config: { boxColor: '#2e001f', shadowColor: '#1a0011', logoColor: '#ff2bc2', boxColorRef: '#470137' } 
            };
            case 'ae': return { 
                svg: SVG_ASSETS.AFTER_EFFECTS, 
                config: { boxColor: '#000045', shadowColor: '#000020', logoColor: '#cf8aff', boxColorRef: '#00005b' } 
            };
            case 'premiere': return { 
                svg: SVG_ASSETS.PREMIERE, 
                config: { boxColor: '#000045', shadowColor: '#000020', logoColor: '#d896ff', boxColorRef: '#00005b' } 
            };
            case 'ai': return { 
                svg: SVG_ASSETS.ILLUSTRATOR, 
                config: { boxColor: '#330000', shadowColor: '#1a0000', logoColor: '#ff9a00', boxColorRef: '#330000' } 
            };
            case 'sub_painter': return { 
                svg: SVG_ASSETS.SUBSTANCE_PAINTER, 
                config: { 
                    boxColor: '#60912f', shadowColor: '#304a18', logoColor: '#ffffff', accentColor: '#60912f', 
                    boxColorRef: '#7cb342', accentColorRef: '#7cb342' 
                } 
            };
            case 'sub_designer': return { 
                svg: SVG_ASSETS.SUBSTANCE_DESIGNER, 
                config: { boxColor: '#c44214', shadowColor: '#63210a', logoColor: '#ffffff', boxColorRef: '#f15b22' } 
            };
            case 'powershell': return { 
                svg: SVG_ASSETS.POWERSHELL, 
                config: { 
                    boxColor: '#012456', shadowColor: '#000810', logoColor: '#3d5c85', accentColor: '#a9c8ff', 
                    isVectorLike: true, outlineWidth: 0.02, logoScale: 0.0055 
                } 
            };
            case 'affinity': return { 
                svg: SVG_ASSETS.AFFINITY, 
                config: { 
                    boxColor: '#a7f175', shadowColor: '#5e8c3d', logoColor: '#1f2e15', 
                    isVectorLike: true, outlineWidth: 0.02, logoScale: 0.0055, depth: 20 
                } 
            };
            case 'id': return {
                svg: SVG_ASSETS.INDESIGN,
                config: { boxColor: '#49021f', shadowColor: '#2a0010', logoColor: '#ff3366', boxColorRef: '#49021f' }
            };
            default: return null;
        }
    }, [renderedId]);

    // LOADING / WAITING STATE
    if (renderedId !== itemId) {
        return (
            <div className="w-full h-full flex flex-col items-center justify-center animate-pulse">
                <div className="w-16 h-16 border-2 border-t-[#F2D019] border-r-transparent border-b-[#F2D019] border-l-transparent rounded-full animate-spin opacity-50 mb-4" />
                <span className="font-mono text-[10px] text-[#F2D019] tracking-widest">INITIALIZING 3D ASSET...</span>
            </div>
        );
    }

    // RENDER LOGIC
    // We use a key here to ensure React treats different items as completely different component trees,
    // forcing a full teardown/setup cycle for the 3D context.
    const componentKey = `viz-${renderedId}`;

    if (standardConfig) {
        return <StandardIcon3D key={componentKey} svgContent={standardConfig.svg} config={standardConfig.config} />;
    }

    switch (renderedId) {
        case '3dsmax': return <ThreeIconViewer key={componentKey} interactive={true} />;
        case 'blender': return <Blender3D key={componentKey} />;
        case 'figma': return <Figma3D key={componentKey} />;
        case 'audition': return <Audition3D key={componentKey} />;
        default: return (
            <div className="w-full h-full flex items-center justify-center opacity-30">
                <span className="font-mono text-xs">NO 3D MODEL</span>
            </div>
        ); 
    }
});

import React, { useState, useCallback } from 'react';
import { ThreeSky } from './components/environment/ThreeSky';
import { Horizon } from './components/environment/Horizon';
import { Floor } from './components/environment/Floor';
import { SandFog } from './components/effects/SandFog';
import { DustParticles } from './components/effects/DustParticles/index';
import { Navigation } from './components/ui/Navigation';
import { IntroScreen } from './components/ui/IntroScreen';
import { OverlayEffects } from './components/ui/OverlayEffects';
import { useParallaxScroll } from './hooks/useParallaxScroll';
import { StackScreen } from './components/ui/StackScreen';
import { LootMapScreen } from './features/LootMapScreen';
import { ProjectsScreen } from './features/ProjectsScreen';
import { ContactScreen } from './features/ContactScreen';
import { InteractionProvider } from './features/InteractionSystem';

type InterfaceType = 'NONE' | 'STACK' | 'LOOTMAP' | 'PROJECTS' | 'CONTACT';

const App: React.FC = () => {
    const [hasStarted, setHasStarted] = useState(false);
    const [activeInterface, setActiveInterface] = useState<InterfaceType>('NONE');

    const { viewerRef, scrollRef, activeIndex, scrollToSection } = useParallaxScroll();

    // --- OPTIMIZED HANDLERS (useCallback) ---
    // Prevents unnecessary re-renders of children when App state (like activeIndex) changes.

    const handleStart = useCallback(() => {
        setHasStarted(true);
    }, []);

    const handleCloseInterface = useCallback(() => {
        setActiveInterface('NONE');
    }, []);

    const handleOpenStack = useCallback(() => {
        setActiveInterface('STACK');
    }, []);

    const handleOpenLootMap = useCallback(() => {
        setActiveInterface('LOOTMAP');
    }, []);

    const handleOpenProjects = useCallback(() => {
        setActiveInterface('PROJECTS');
    }, []);

    const handleOpenContact = useCallback(() => {
        setActiveInterface('CONTACT');
    }, []);

    return (
        <InteractionProvider>
            <div className="bg-black overflow-hidden relative h-screen w-screen select-none font-sans text-white antialiased">

                {/* INTERFACES (MODALS) */}
                {activeInterface === 'STACK' && <StackScreen onClose={handleCloseInterface} />}
                {activeInterface === 'LOOTMAP' && <LootMapScreen onClose={handleCloseInterface} />}
                {activeInterface === 'PROJECTS' && <ProjectsScreen onClose={handleCloseInterface} />}
                {activeInterface === 'CONTACT' && <ContactScreen onClose={handleCloseInterface} />}

                {/* PANTALLA DE INICIO */}
                {!hasStarted && <IntroScreen onStart={handleStart} />}

                {/* POST-PROCESADO */}
                <OverlayEffects />

                {/* 1. LAYER: ENVIRONMENT */}
                <div className="absolute inset-0 z-0 pointer-events-none">
                    <ThreeSky scrollRef={scrollRef} />
                </div>

                {/* 2. LAYER: WORLD */}
                <div 
                    ref={viewerRef}
                    id="viewer" 
                    className="relative z-10 w-full h-full overflow-x-auto scroll-smooth snap-x snap-mandatory flex flex-row [&::-webkit-scrollbar]:hidden [-ms-overflow-style:'none'] [scrollbar-width:'none']"
                >
                    {/* Horizon is heavily memoized, so stable props are crucial here */}
                    <Horizon 
                        onOpenStack={handleOpenStack} 
                        onOpenLootMap={handleOpenLootMap}
                        onOpenProjects={handleOpenProjects}
                        onOpenContact={handleOpenContact}
                        activeIndex={activeIndex}
                        enableAnimations={hasStarted}
                    />
                    <Floor />

                    <div className="min-w-[100vw] h-full flex-shrink-0 snap-start pointer-events-none" />
                    <div className="min-w-[100vw] h-full flex-shrink-0 snap-start pointer-events-none" />
                    <div className="min-w-[100vw] h-full flex-shrink-0 snap-start pointer-events-none" />
                </div>

                {/* 3. LAYER: EFFECTS */}
                <SandFog scrollRef={scrollRef} />
                <DustParticles scrollRef={scrollRef} />

                {/* 4. LAYER: UI (HUD) */}
                <div className={`transition-opacity duration-1000 ${hasStarted ? 'opacity-100' : 'opacity-0'}`}>
                    <Navigation 
                        totalPanes={3} 
                        activeIndex={activeIndex} 
                        onDotClick={scrollToSection} 
                    />
                </div>
            </div>
        </InteractionProvider>
    );
};

export default App;

import React, { Component, ErrorInfo, ReactNode } from 'react';

interface Props {
    children: ReactNode;
    fallback?: ReactNode;
}

interface State {
    hasError: boolean;
}

export class ErrorBoundary extends Component<Props, State> {
    public state: State = {
        hasError: false
    };

    public static getDerivedStateFromError(_: Error): State {
        return { hasError: true };
    }

    public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
        console.error("Unibelands 3D System Error:", error, errorInfo);
    }

    public render() {
        if (this.state.hasError) {
            return this.props.fallback || (
                <div className="w-full h-full flex flex-col items-center justify-center bg-black/80 border border-red-900/50 rounded-lg p-4">
                    <div className="text-red-500 font-mono text-xs tracking-widest mb-2">SYSTEM FAILURE</div>
                    <div className="w-8 h-8 border-2 border-red-500/30 border-t-red-500 rounded-full animate-spin"/>
                    <span className="text-[10px] text-red-400/60 mt-2 font-mono">RENDER_CONTEXT_LOST</span>
                </div>
            );
        }

        return this.props.children;
    }
}

import React from 'react';
import { StackItem, WeaponConfig, isWeapon } from '../types';
import { ExtendedStackItem } from '../data';
import { SkillIcons } from '../assets/SkillIcons';
import { Visualizer3D } from './3d/Visualizer3D';
import { ErrorBoundary } from '../../../components/ui/ErrorBoundary';

interface InspectorPanelProps {
    selectedItem: StackItem | WeaponConfig;
    animateCard: boolean;
    themeColor?: string;
}

const RARITY_COLORS: Record<string, string> = {
    common: '#9ca3af',
    rare: '#3b82f6',
    epic: '#a855f7',
    legendary: '#f59e0b',
    mystic: '#ef4444'
};

export const InspectorPanel: React.FC<InspectorPanelProps> = React.memo(({ selectedItem, animateCard, themeColor = '#F2D019' }) => {

    const rarity = selectedItem.rarity || 'common';
    const rarityColor = RARITY_COLORS[rarity] || '#ffffff';
    const accentColor = isWeapon(selectedItem) ? themeColor : rarityColor; 

    const extendedItem = !isWeapon(selectedItem) ? (selectedItem as ExtendedStackItem) : null;
    const IconComponent = extendedItem?.iconKey ? SkillIcons[extendedItem.iconKey] : null;

    const has3D = ['3dsmax', 'blender', 'figma', 'xd', 'ae', 'premiere', 'ai', 'sub_painter', 'sub_designer', 'powershell', 'id', 'ps', 'affinity', 'audition'].includes(selectedItem.id);

    const stats = selectedItem.stats;
    const averageScore = Math.round((stats.knowledge + stats.versatility + stats.interface + stats.learning) / 4);

    return (
        <div className={`
            w-full h-full flex flex-col relative transition-all duration-300 select-none overflow-hidden
            ${animateCard ? 'opacity-50 scale-[0.99]' : 'opacity-100 scale-100'}
        `}>
            {/* 1. HEADER (Absolute Top) */}
            <div className="w-full z-20 flex justify-between items-start pointer-events-none p-6 shrink-0">
                <div>
                    <div className="flex items-center gap-3 mb-1 opacity-60">
                        <span className="text-[10px] font-mono tracking-[0.2em] font-bold text-white uppercase bg-white/10 px-2 py-0.5 rounded">
                            {isWeapon(selectedItem) ? selectedItem.subtitle : (selectedItem as StackItem).manufacturer}
                        </span>
                        <div className="h-[1px] w-12 bg-white/30" />
                    </div>
                    <h2 className="font-['Teko'] text-7xl font-bold uppercase leading-[0.8] text-white tracking-tight drop-shadow-xl truncate max-w-md">
                        {selectedItem.name}
                    </h2>
                </div>

                {/* VISUAL SCORE BADGE */}
                <div className="flex flex-col items-end">
                    <div className="text-[10px] font-mono text-gray-400 tracking-widest mb-1">OVERALL RATING</div>
                    <div className="flex items-baseline">
                        <span className="font-['Teko'] text-6xl font-bold text-white leading-none" style={{ textShadow: `0 0 20px ${accentColor}` }}>
                            {averageScore}
                        </span>
                        <span className="text-xl text-gray-500 font-bold">/100</span>
                    </div>
                </div>
            </div>

            {/* 2. CENTER PIECE (Flexible Container - Prevents overflow) */}
            <div className="flex-1 min-h-0 w-full flex items-center justify-center relative z-10 py-4">
                <div className="w-full h-full flex items-center justify-center relative">
                    {/* Background Glow */}
                    <div 
                        className="absolute inset-0 opacity-15 pointer-events-none"
                        style={{ background: `radial-gradient(circle at center, ${accentColor} 0%, transparent 60%)` }}
                    />

                    {/* Icon Container with Max Size Constraints */}
                    <div className="w-full h-full max-w-[80%] max-h-[80%] flex items-center justify-center">
                        {has3D ? (
                            <div className="w-full h-full">
                                <ErrorBoundary fallback={
                                    <div className="w-full h-full flex items-center justify-center opacity-50">
                                        <img src={extendedItem?.icon || selectedItem.icon} className="max-h-[60%] max-w-[60%] object-contain grayscale opacity-50" alt="Fallback" />
                                    </div>
                                }>
                                    <Visualizer3D itemId={selectedItem.id} />
                                </ErrorBoundary>
                            </div>
                        ) : isWeapon(selectedItem) ? (
                            <img src={selectedItem.image} alt={selectedItem.name} className="h-full w-auto max-h-full object-contain drop-shadow-2xl animate-float" />
                        ) : (
                            <div className="relative w-full h-full flex items-center justify-center">
                                {IconComponent ? (
                                    <IconComponent className="w-full h-full max-w-[250px] max-h-[250px] object-contain drop-shadow-2xl animate-float" />
                                ) : (
                                    <img src={selectedItem.icon} className="w-full h-full max-w-[250px] max-h-[250px] object-contain animate-float" alt="Icon" />
                                )}
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {/* 3. FOOTER STATS (Pinned Bottom) */}
            <div className="mt-auto shrink-0 bg-black/40 backdrop-blur-md border-t border-white/10 p-8 w-full">
                <div className="flex flex-col md:flex-row gap-12">

                    {/* STATS COLUMN */}
                    <div className="flex-1 space-y-5">
                        <div className="flex items-center gap-2 mb-4">
                            <div className="w-2 h-2 bg-white rotate-45" />
                            <span className="text-xs font-mono text-white/50 tracking-[0.3em] font-bold uppercase">PERFORMANCE METRICS</span>
                        </div>

                        <StatBar label="CONOCIMIENTO SOFTWARE" value={stats.knowledge} color="#00F0FF" />
                        <StatBar label="VERSATILIDAD PLATAFORMA" value={stats.versatility} color="#F2D019" />
                        <StatBar label="DOMINIO INTERFACE" value={stats.interface} color="#22c55e" />
                        <StatBar label="CURVA APRENDIZAJE" value={stats.learning} color="#ef4444" />
                    </div>

                    {/* INFO COLUMN */}
                    <div className="flex-1 border-l border-white/10 pl-8 flex flex-col justify-between">
                        <div>
                            <div className="text-[10px] font-mono text-gray-500 uppercase tracking-widest mb-2">DESCRIPTION</div>
                            <p className="font-['Roboto_Mono'] text-sm text-gray-300 leading-relaxed line-clamp-3">
                                {selectedItem.description}
                            </p>
                        </div>

                        <div className="mt-6 flex justify-between items-end">
                            <div>
                                <div className="text-[10px] font-mono text-gray-500 uppercase tracking-widest">RARITY CLASS</div>
                                <div className="font-['Teko'] text-4xl uppercase font-bold tracking-wide leading-none" style={{ color: rarityColor }}>
                                    {rarity}
                                </div>
                            </div>
                            <div className="flex gap-1 mb-1">
                                {[...Array(5)].map((_, i) => (
                                    <div key={i} className={`w-2 h-4 transform skew-x-[-15deg] ${i < (['common','rare','epic','legendary','mystic'].indexOf(rarity) + 1) ? 'bg-white' : 'bg-white/10'}`} style={{ backgroundColor: i < (['common','rare','epic','legendary','mystic'].indexOf(rarity) + 1) ? rarityColor : undefined }} />
                                ))}
                            </div>
                        </div>
                    </div>

                </div>
            </div>
        </div>
    );
});

const StatBar = ({ label, value, color }: { label: string, value: number, color: string }) => {
    const totalCells = 20;
    const filledCells = Math.round((value / 100) * totalCells);

    return (
        <div className="flex flex-col gap-1">
            <div className="flex justify-between items-end">
                <span className="text-[11px] font-bold text-white tracking-widest uppercase">{label}</span>
                <span className="font-mono text-xs font-bold" style={{ color }}>{value}%</span>
            </div>
            <div className="flex gap-[2px] h-2">
                {[...Array(totalCells)].map((_, i) => (
                    <div 
                        key={i}
                        className={`flex-1 transform skew-x-[-20deg] transition-all duration-300 ${i < filledCells ? 'opacity-100' : 'opacity-20'}`}
                        style={{ 
                            backgroundColor: i < filledCells ? color : '#333',
                            boxShadow: i < filledCells ? `0 0 5px ${color}` : 'none'
                        }}
                    />
                ))}
            </div>
        </div>
    );
};

@tailwind base;
@tailwind components;
@tailwind utilities;

/* --- CONFIGURACIÓN GLOBAL --- */
html, body, #root {
    cursor: auto !important;
    background-color: black;
}

/* --- INTERACTION SYSTEM --- */
.interaction-target {
    transition: filter 0.2s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    cursor: crosshair; /* Tactical feel */
    pointer-events: auto !important; /* CRITICAL: Ensures interaction works inside pointer-events-none containers */
}

/* White Outline Effect using multiple drop-shadows for a stroke-like appearance on PNGs */
.interaction-target:hover {
    filter: drop-shadow(1px 0 0 white) 
            drop-shadow(-1px 0 0 white) 
            drop-shadow(0 1px 0 white) 
            drop-shadow(0 -1px 0 white)
            brightness(1.1);
    z-index: 50;
}

/* --- SCROLLBAR PERSONALIZADO SCI-FI --- */
.sci-fi-scroll {
    scrollbar-width: thin;
    scrollbar-color: #333 rgba(255, 255, 255, 0.05);
}

.sci-fi-scroll::-webkit-scrollbar {
    width: 6px;
    height: 6px;
}

.sci-fi-scroll::-webkit-scrollbar-track {
    background: rgba(0, 0, 0, 0.3);
}

.sci-fi-scroll::-webkit-scrollbar-thumb {
    background: #444;
    border-radius: 10px;
    transition: background 0.2s;
}

.sci-fi-scroll::-webkit-scrollbar-thumb:hover {
    background: #F2D019;
}

/* --- ANIMACIONES DE ALTO RENDIMIENTO (GPU) --- */
@keyframes drift-slow {
    0% { transform: translateX(0); }
    100% { transform: translateX(-25%); }
}

@keyframes morph {
    0% { border-radius: 60% 40% 30% 70% / 60% 30% 70% 40%; }
    50% { border-radius: 30% 60% 70% 40% / 50% 60% 30% 60%; }
    100% { border-radius: 60% 40% 30% 70% / 60% 30% 70% 40%; }
}

@keyframes undulate {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-25px); }
}

@keyframes grain-flow {
    0% { transform: translate(0, 0); }
    100% { transform: translate(-5%, -5%); }
}

@keyframes scanline-move {
    0% { top: -10%; opacity: 0; }
    10% { opacity: 1; }
    90% { opacity: 1; }
    100% { top: 110%; opacity: 0; }
}

@keyframes portal-pulse {
    0%, 100% { filter: drop-shadow(0 0 15px rgba(0, 240, 255, 0.4)) brightness(1); }
    50% { filter: drop-shadow(0 0 40px rgba(0, 240, 255, 0.8)) brightness(1.2); }
}

@keyframes glitch-text {
    0% { transform: translate(0); text-shadow: 2px 2px 0px #000; }
    2% { transform: translate(-2px, 2px); text-shadow: -2px 0 cyan, 2px 0 red; }
    4% { transform: translate(2px, -1px); text-shadow: 2px 0 cyan, -2px 0 red; }
    6% { transform: translate(0); }
    100% { transform: translate(0); }
}

@keyframes energy-arc {
    0% { transform: scaleX(0) translateX(-100%); opacity: 0; }
    50% { transform: scaleX(1) translateX(0); opacity: 1; }
    100% { transform: scaleX(0) translateX(100%); opacity: 0; }
}

@keyframes float-tech {
    0%, 100% { transform: translateY(0) rotate(0deg); }
    50% { transform: translateY(-15px) rotate(5deg); }
}

/* --- NUEVAS ANIMACIONES DE INTERFAZ --- */

/* Movimiento de fondo infinito */
@keyframes bg-pan {
    0% { background-position: 0% 0%; }
    100% { background-position: 100px 100px; }
}

/* Entrada secuencial (Stagger) */
@keyframes fade-up {
    0% { opacity: 0; transform: translateY(30px); }
    100% { opacity: 1; transform: translateY(0); }
}

/* --- HINT PULSE (One Shot - Light Only) --- */
@keyframes guide-pulse {
    0% { 
        filter: brightness(1) drop-shadow(0 0 0 rgba(0,0,0,0)); 
    }
    20% { 
        filter: brightness(1.3) drop-shadow(0 0 15px rgba(0, 240, 255, 0.6)); 
    }
    40% { 
        filter: brightness(1.1) drop-shadow(0 0 5px rgba(0, 240, 255, 0.3)); 
    }
    60% { 
        filter: brightness(1.25) drop-shadow(0 0 10px rgba(0, 240, 255, 0.5)); 
    }
    100% { 
        filter: brightness(1) drop-shadow(0 0 0 rgba(0,0,0,0)); 
    }
}

.animate-portal-fx { animation: portal-pulse 3s ease-in-out infinite; }
.animate-glitch-active { animation: glitch-text 4s linear infinite; }
.animate-energy { animation: energy-arc 2s cubic-bezier(0.4, 0, 0.2, 1) infinite; }
.animate-float-tech { animation: float-tech 6s ease-in-out infinite; }

.animate-stack-entry { animation: stack-entry 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
.animate-grain { animation: grain-flow 0.5s steps(3) infinite; }
.animate-drift { animation: drift-slow 80s linear infinite; }
.animate-blob-1 { animation: morph 10s ease-in-out infinite, undulate 6s ease-in-out infinite alternate; }
.animate-blob-2 { animation: morph 14s ease-in-out infinite, undulate 8s ease-in-out infinite alternate; }
.animate-blob-3 { animation: morph 11s ease-in-out infinite, undulate 5s ease-in-out infinite alternate; }
.animate-float { animation: undulate 6s ease-in-out infinite; }
.animate-scanline { animation: scanline-move 4s linear infinite; }
