.echo-stats-grid.active { animation: element-pop 0.7s var(--transition-bouncy) forwards; }

.echo-stats-grid:hover .echo-stat-box:not(:hover) { opacity: 0.7; filter: saturate(0.7) brightness(0.85); transform: scale(0.95) translateY(3px); }
.echo-stats-grid:hover .echo-stat-box:not(:hover) .echo-stat-tag { opacity: 1; filter: drop-shadow(0 0 8px var(--yellow)) brightness(1.1); }

.echo-stat-box {
    background: linear-gradient(145deg, rgba(8, 20, 28, 0.98) 0%, rgba(3, 12, 18, 0.99) 100%);
    backdrop-filter: blur(16px); position: relative; display: flex; flex-direction: column;
    justify-content: center; align-items: center; padding: 1.5cqw; aspect-ratio: 2; overflow: visible;
    border-radius: 0.8cqw; border: 1px solid rgba(45, 212, 191, 0.25);
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.6), 0 0 1px rgba(45, 212, 191, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.05), inset 0 0 30px rgba(45, 212, 191, 0.03);
    transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.4s cubic-bezier(0.23, 1, 0.32, 1), border-color 0.3s ease, background 0.4s ease;
    will-change: transform, box-shadow; cursor: pointer; z-index: 1;
}
.echo-stat-box:hover {
    transform: translateY(-8px) scale(1.12);
    background: linear-gradient(145deg, rgba(15, 30, 40, 0.99) 0%, rgba(8, 20, 28, 1) 100%);
    border-color: var(--yellow);
    animation: border-glow-pulse 2s ease-in-out infinite; z-index: 100;
}

.echo-stat-tag {
    position: absolute; top: -1px; right: 12%; width: 3.5cqw; height: 1.2cqw;
    background: linear-gradient(135deg, var(--yellow) 0%, #fde047 50%, var(--yellow) 100%);
    clip-path: polygon(0 0, 100% 0, 100% 100%, 15% 100%); z-index: 999;
    box-shadow: 0 2px 8px rgba(250, 204, 21, 0.4);
    transition: all 0.35s cubic-bezier(0.34, 1.56, 0.64, 1); pointer-events: none;
}
.echo-stat-box:hover .echo-stat-tag {
    width: 4.5cqw; height: 1.5cqw;
    background: linear-gradient(135deg, #fef08a 0%, var(--yellow) 40%, #f59e0b 100%);
    box-shadow: 0 4px 15px rgba(250, 204, 21, 0.6), 0 0 25px rgba(250, 204, 21, 0.4);
    animation: tag-bounce 0.6s ease-out;
}

.echo-stat-box::before {
    content: ""; position: absolute; inset: 3px; border: 1px solid rgba(45, 212, 191, 0.1);
    border-radius: 0.6cqw; pointer-events: none;
    background: radial-gradient(ellipse at top, rgba(45, 212, 191, 0.03) 0%, transparent 60%), radial-gradient(ellipse at bottom, rgba(250, 204, 21, 0.02) 0%, transparent 60%);
    opacity: 1; transition: all 0.4s ease;
}
.echo-stat-box:hover::before {
    border-color: rgba(250, 204, 21, 0.3);
    background: radial-gradient(ellipse at top, rgba(250, 204, 21, 0.08) 0%, transparent 50%), radial-gradient(ellipse at bottom, rgba(45, 212, 191, 0.05) 0%, transparent 50%);
    animation: energy-ring 1.5s ease-in-out infinite;
}

.echo-stat-box::after {
    content: ""; position: absolute; top: 0; left: 10%; width: 80%; height: 2px;
    background: linear-gradient(90deg, transparent 0%, rgba(250, 204, 21, 0.3) 20%, var(--yellow) 50%, rgba(250, 204, 21, 0.3) 80%, transparent 100%);
    opacity: 0; border-radius: 2px; pointer-events: none; transition: opacity 0.3s;
}
.echo-stat-box:hover::after { opacity: 1; animation: scanline-sweep 1.2s ease-in-out infinite; }

.echo-stat-icon-wrapper {
    position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
    width: 100%; height: 100%; display: flex; justify-content: center; align-items: center;
    opacity: 0.03; transition: all 0.5s cubic-bezier(0.23, 1, 0.32, 1); pointer-events: none;
}
.echo-stat-icon { width: 85%; height: 85%; stroke: var(--teal); filter: blur(0.5px); transition: all 0.4s; }
.echo-stat-box:hover .echo-stat-icon-wrapper { opacity: 0.15; transform: translate(-50%, -50%) scale(1.3) rotate(5deg); }
.echo-stat-box:hover .echo-stat-icon { stroke: var(--yellow); filter: blur(0) drop-shadow(0 0 10px rgba(250, 204, 21, 0.3)); }

.echo-stat-value {
    font-family: 'Anton', sans-serif; font-size: 9cqw; color: #fff; line-height: 1; z-index: 2;
    text-shadow: 0 0 20px rgba(45, 212, 191, 0.15); transition: all 0.35s cubic-bezier(0.23, 1, 0.32, 1); position: relative;
}
.echo-stat-box:hover .echo-stat-value {
    color: var(--teal); transform: scale(1.08) translateY(-2px);
    background: linear-gradient(90deg, var(--teal) 0%, var(--teal) 40%, #fff 50%, var(--teal) 60%, var(--teal) 100%);
    background-size: 200% 100%; -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
    animation: shimmer-effect 2s ease-in-out infinite, value-glow 1.5s ease-in-out infinite;
}

.echo-stat-label {
    font-family: 'Share Tech Mono', monospace; font-size: 2cqw; color: rgba(45, 212, 191, 0.5);
    margin-top: 0.5cqw; letter-spacing: 0.4cqw; text-transform: uppercase; z-index: 2;
    transition: all 0.4s cubic-bezier(0.23, 1, 0.32, 1); position: relative;
}
.echo-stat-box:hover .echo-stat-label {
    color: rgba(250, 204, 21, 0.9); letter-spacing: 0.8cqw; transform: translateY(2px);
    text-shadow: 0 0 15px rgba(250, 204, 21, 0.4);
}

import React, { useEffect, useRef } from 'react';

interface EchoPortalProps {
    trigger?: boolean;
}

export const EchoPortal: React.FC<EchoPortalProps> = ({ trigger = false }) => {
    const laserRef = useRef<HTMLDivElement>(null);
    const titlesRef = useRef<HTMLElement>(null);
    const bannerRef = useRef<HTMLDivElement>(null);
    const paragraphRef = useRef<HTMLDivElement>(null);
    const statsRef = useRef<HTMLElement>(null);

    useEffect(() => {
        const refs = [laserRef, titlesRef, bannerRef, paragraphRef, statsRef];

        // Limpiar clases al desmontar o reiniciar
        const reset = () => {
            refs.forEach(ref => {
                if (ref.current) ref.current.classList.remove('active');
            });
        };

        if (trigger) {
            reset();

            const sequence = [
                { ref: laserRef, delay: 100 },
                { ref: titlesRef, delay: 500 },
                { ref: bannerRef, delay: 1100 },
                { ref: paragraphRef, delay: 1600 },
                { ref: statsRef, delay: 2000 }
            ];

            const timeouts: ReturnType<typeof setTimeout>[] = [];

            sequence.forEach(item => {
                const t = setTimeout(() => {
                    if (item.ref.current) {
                        item.ref.current.classList.add('active');
                    }
                }, item.delay);
                timeouts.push(t);
            });

            return () => timeouts.forEach(clearTimeout);
        } else {
            reset();
        }
    }, [trigger]);

    return (
        <div className="relative w-[44vh] aspect-[2/3] md:w-[58vh] pointer-events-auto cursor-pointer group echo-portal-root">
            <div className="echo-scene">
                {/* Tarjeta Base Holográfica (BG Hex) */}
