                </div>

                {/* Efectos de Luz y Personaje (Superpuesto en Z-Index 20) */}
                <div className="echo-hologram-wrapper">
                    <img 
                        src="https://i.imgur.com/UlHz9On.png" 
                        alt="Avatar Vault Hunter" 
                        className="echo-img" 
                        referrerPolicy="no-referrer"
                    />
                </div>

                {/* Capa de Interfaz UI (Z-Index 30) */}
                <div className="echo-ui">
                    {/* Bloque de Identidad */}
                    <header className="echo-txt-container" ref={titlesRef}>
                        <h1 className="echo-line-title echo-line-uiux">UI/UX</h1>
                        <h2 className="echo-line-title echo-line-designer">GAME DESIGNER</h2>

                        <div className="echo-status-banner" ref={bannerRef}>
                            <div className="echo-hazard-bar" aria-hidden="true"></div>
                            <span className="echo-status-text">INTELLIGENCE SYSTEMS</span>
                            <div className="echo-hazard-bar" style={{left: 'auto', right: 0}}></div>
                        </div>

                        {/* Párrafo Descriptivo */}
                        <div className="echo-data-container" ref={paragraphRef}>
