export const getPreloadList = (): string[] => {
    const list: string[] = [];
    const recurse = (obj: any) => {
        Object.values(obj).forEach(val => {
            if (typeof val === 'string') list.push(val);
            else if (Array.isArray(val)) list.push(...val);
            else if (typeof val === 'object') recurse(val);
        });
    };
    recurse(ASSETS);
    return list;
};

